// Failed runs are never silent: they surface here.
// Production: replace the log with a Slack / Discord / email alert node.
const e = $input.first().json;
const workflow = e.workflow ? e.workflow.name : 'unknown workflow';
const node = e.execution && e.execution.lastNodeExecuted ? e.execution.lastNodeExecuted : 'unknown node';
const message = e.execution && e.execution.error ? e.execution.error.message : 'unknown error';
console.error(`[LendLoop ALERT] "${workflow}" failed at "${node}": ${message}`);
return [{ json: { workflow, node, message, executionId: e.execution ? e.execution.id : null } }];
